function decodeLines(raw       )                                          {
  const lines                = raw.map(([alignCode, runs]                 ) => ({
    align: alignCode === 1 ? "left" : "center",
    runs: runs.map((r       ) => ({
      text: r[0],
      fontSize: r[1],
      color: r[2] ?? "#000000",
      bold: r[3] !== undefined ? r[3] === 1 : true,
      fontFamily: r[4] === 1 ? "Times New Roman" : "Calibri",
      underline: r[5] === 1,
    })),
  }));
  const plain = lines.map((l) => l.runs.map((r) => r.text).join("")).join(" ").trim();
  return { lines, plain };
}
const VERTICES              = [...RAW_VERTICES_1, ...RAW_VERTICES_2].map((r)            => {
  const { lines, plain } = decodeLines(r[8]);
  const o = r[9] || {};
  return {
    id: r[0],
    parentId: o.p ?? "1",
    zOrder: r[1],
    x: r[2],
    y: r[3],
    width: r[4],
    height: r[5],
    rotation: o.rot ?? 0,
    flipH: o.fh === 1,
    stencilId: o.s ?? null,
    fillColor: o.fc ?? "#ffffff",
    gradientColor: o.gc ?? "none",
    gradientDirection: o.gd ?? "south",
    fillOpacity: o.fo ?? 1,
    strokeColor: o.sc ?? "#000000",
    strokeWidth: o.sw ?? 1,
    strokeOpacity: o.so ?? 1,
    dashed: o.d === 1,
    align: o.a === 1 ? "left" : "center",
    plainText: plain,
    lines,
    category: r[6]                  ,
    region: r[7]            ,
  };
});
const EDGES            = RAW_EDGES.map((r)          => {
  const { lines, plain } = decodeLines(r[10]);
  const o = r[11] || {};
  return {
    id: r[0],
    zOrder: r[1],
    sourceX: r[2],
    sourceY: r[3],
    targetX: r[4],
    targetY: r[5],
    strokeColor: r[6],
    strokeWidth: r[7],
    dashed: o.d === 1,
    startArrow: o.sa === 1,
    endArrow: o.ea === 1,
    labelPlainText: plain,
    labelLines: lines,
    labelRotation: o.rot ?? 0,
    labelBgColor: o.bg ?? "#ffffff",
    labelOffsetX: o.ox ?? 0,
    labelOffsetY: o.oy ?? 0,
    category: r[8]                 ,
    region: r[9]            ,
  };
});


// --- src/renderer/svgDiagram.ts ---

const SVG_NS = 'http://www.w3.org/2000/svg';

                                
                    
                          
                          
                                
                         
                      
                            
                           
 

function escapeId(raw        )         {
  return raw.replace(/[^a-zA-Z0-9_-]/g, '');
}

function resolveFontFamily(family        )         {
  if (family.toLowerCase().includes('times')) {
    return "'Times New Roman', Times, serif";
  }
  return "'Calibri', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
}

function createTextGroup(
  lines               ,
  boxWidth        ,
  boxHeight        
)              {
  const g = document.createElementNS(SVG_NS, 'g');
  g.setAttribute('class', 'wan-label-group');

  const lineHeights = lines.map((line) => {
    const maxFs = Math.max(...line.runs.map((r) => r.fontSize), 12);
    return maxFs * 1.18;
  });
  const totalHeight = lineHeights.reduce((acc, h) => acc + h, 0);
  let currentY = (boxHeight - totalHeight) / 2;

  lines.forEach((line, idx) => {
    const lineH = lineHeights[idx];
    const maxFs = Math.max(...line.runs.map((r) => r.fontSize), 12);
    const baselineY = currentY + maxFs * 0.84;
    currentY += lineH;

    const textEl = document.createElementNS(SVG_NS, 'text');
    const isLeft = line.align === 'left';
    const xPos = isLeft ? 4 : boxWidth / 2;

    textEl.setAttribute('x', xPos.toFixed(2));
    textEl.setAttribute('y', baselineY.toFixed(2));
    textEl.setAttribute('text-anchor', isLeft ? 'start' : 'middle');
    textEl.setAttribute('xml:space', 'preserve');

    for (const run of line.runs) {
      const tspan = document.createElementNS(SVG_NS, 'tspan');
      tspan.textContent = run.text;
      tspan.setAttribute('fill', run.color || '#000000');
      tspan.setAttribute('font-size', `${run.fontSize}px`);
      tspan.setAttribute('font-family', resolveFontFamily(run.fontFamily));
      if (run.bold) {
        tspan.setAttribute('font-weight', '700');
      }
      if (run.underline) {
        tspan.setAttribute('text-decoration', 'underline');
      }
      textEl.appendChild(tspan);
    }

    g.appendChild(textEl);
  });

  return g;
}

function createArrowPolygon(
  tipX        ,
  tipY        ,
  fromX        ,
  fromY        ,
  color        ,
  strokeWidth        
)                           {
  const dx = tipX - fromX;
  const dy = tipY - fromY;
  const len = Math.hypot(dx, dy);
  if (len < 1e-3) return null;

  const ux = dx / len;
  const uy = dy / len;
  const size = Math.max(8, strokeWidth * 3.2);
  const halfWidth = size * 0.52;

  const baseX = tipX - ux * size;
  const baseY = tipY - uy * size;
  const leftX = baseX - uy * halfWidth;
  const leftY = baseY + ux * halfWidth;
  const rightX = baseX + uy * halfWidth;
  const rightY = baseY - ux * halfWidth;

  const poly = document.createElementNS(SVG_NS, 'polygon');
  poly.setAttribute(
    'points',
    `${tipX.toFixed(2)},${tipY.toFixed(2)} ${leftX.toFixed(2)},${leftY.toFixed(2)} ${rightX.toFixed(2)},${rightY.toFixed(2)}`
  );
  poly.setAttribute('fill', color);
  return poly;
}
function buildDiagramSvg(
  svg               ,
  vertices             ,
  edges           
)   
                                       
                                  
                                   
  {
  svg.innerHTML = '';
  const elementMap = new Map                     ();
  const boundaryElements                = [];
  const edgeLabelElements                = [];

  // 1. <defs> for gradients and grid pattern
  const defs = document.createElementNS(SVG_NS, 'defs');

  // Subtle CAD grid pattern
  const smallGrid = document.createElementNS(SVG_NS, 'pattern');
  smallGrid.setAttribute('id', 'wan-grid-small');
  smallGrid.setAttribute('width', '50');
  smallGrid.setAttribute('height', '50');
  smallGrid.setAttribute('patternUnits', 'userSpaceOnUse');
  const smallPath = document.createElementNS(SVG_NS, 'path');
  smallPath.setAttribute('d', 'M 50 0 L 0 0 0 50');
  smallPath.setAttribute('fill', 'none');
  smallPath.setAttribute('stroke', 'rgba(148, 163, 184, 0.16)');
  smallPath.setAttribute('stroke-width', '1');
  smallGrid.appendChild(smallPath);
  defs.appendChild(smallGrid);

  const largeGrid = document.createElementNS(SVG_NS, 'pattern');
  largeGrid.setAttribute('id', 'wan-grid-large');
  largeGrid.setAttribute('width', '250');
  largeGrid.setAttribute('height', '250');
  largeGrid.setAttribute('patternUnits', 'userSpaceOnUse');
  const rectGrid = document.createElementNS(SVG_NS, 'rect');
  rectGrid.setAttribute('width', '250');
  rectGrid.setAttribute('height', '250');
  rectGrid.setAttribute('fill', 'url(#wan-grid-small)');
  const largePath = document.createElementNS(SVG_NS, 'path');
  largePath.setAttribute('d', 'M 250 0 L 0 0 0 250');
  largePath.setAttribute('fill', 'none');
  largePath.setAttribute('stroke', 'rgba(148, 163, 184, 0.32)');
  largePath.setAttribute('stroke-width', '1.5');
  largeGrid.appendChild(rectGrid);
  largeGrid.appendChild(largePath);
  defs.appendChild(largeGrid);

  // Collect unique gradients from vertices
  const gradientMap = new Map                ();
  for (const v of vertices) {
    if (
      v.fillColor !== 'none' &&
      v.gradientColor !== 'none' &&
      v.fillColor.toLowerCase() !== v.gradientColor.toLowerCase()
    ) {
      const key = `${v.fillColor}_${v.gradientColor}_${v.gradientDirection}`;
      if (!gradientMap.has(key)) {
        const gradId = `grad-${ escapeId(key) }`;
        gradientMap.set(key, gradId);
        const lg = document.createElementNS(SVG_NS, 'linearGradient');
        lg.setAttribute('id', gradId);
        lg.setAttribute('x1', '0%');
        lg.setAttribute('x2', '0%');
        if (v.gradientDirection === 'north') {
          lg.setAttribute('y1', '100%');
          lg.setAttribute('y2', '0%');
        } else {
          lg.setAttribute('y1', '0%');
          lg.setAttribute('y2', '100%');
        }
        const stop1 = document.createElementNS(SVG_NS, 'stop');
        stop1.setAttribute('offset', '0%');
        stop1.setAttribute('stop-color', v.fillColor);
        const stop2 = document.createElementNS(SVG_NS, 'stop');
        stop2.setAttribute('offset', '100%');
        stop2.setAttribute('stop-color', v.gradientColor);
        lg.appendChild(stop1);
        lg.appendChild(stop2);
        defs.appendChild(lg);
      }
    }
  }

  svg.appendChild(defs);

  // 2. Viewport Root Group
  const viewportGroup = document.createElementNS(SVG_NS, 'g');
  viewportGroup.setAttribute('id', 'wan-viewport');

  // Canvas paper background
  const paperBg = document.createElementNS(SVG_NS, 'rect');
  paperBg.setAttribute('id', 'wan-paper-bg');
  paperBg.setAttribute('x', '60');
  paperBg.setAttribute('y', '60');
  paperBg.setAttribute('width', '6110');
  paperBg.setAttribute('height', '4120');
  paperBg.setAttribute('rx', '8');
  paperBg.setAttribute('fill', '#ffffff');
  viewportGroup.appendChild(paperBg);

  // Grid overlay
  const gridRect = document.createElementNS(SVG_NS, 'rect');
  gridRect.setAttribute('id', 'wan-grid-overlay');
  gridRect.setAttribute('x', '106');
  gridRect.setAttribute('y', '106');
  gridRect.setAttribute('width', '6019');
  gridRect.setAttribute('height', '4032');
  gridRect.setAttribute('fill', 'url(#wan-grid-large)');
  gridRect.setAttribute('pointer-events', 'none');
  viewportGroup.appendChild(gridRect);

  // Combine vertices and edges in exact Z-order, keeping frame và boundaries behind interactive nodes
                   
                                                           
                                                        

  const renderList               = [];

  for (const v of vertices) {
    let priority = 2;
    if (v.category === 'frame') priority = 0;
    else if (v.category === 'boundary' || v.id === '2') priority = 1;
    else if (v.category === 'cloud') priority = 1.5;
    renderList.push({ kind: 'vertex', item: v, priority });
  }

  for (const e of edges) {
    renderList.push({ kind: 'edge', item: e, priority: 1.8 });
  }

  renderList.sort((a, b) => {
    if (a.priority !== b.priority) return a.priority - b.priority;
    return a.item.zOrder - b.item.zOrder;
  });

  for (const entry of renderList) {
    if (entry.kind === 'vertex') {
      const v = entry.item;
      const g = document.createElementNS(SVG_NS, 'g');
      g.setAttribute('class', `wan-element wan-vertex cat-${v.category}`);
      g.setAttribute('data-id', v.id);
      g.setAttribute('data-kind', 'vertex');
      g.setAttribute('data-category', v.category);
      g.setAttribute('data-region', v.region);

      const cx = v.width / 2;
      const cy = v.height / 2;
      const transform =
        v.rotation !== 0
          ? `translate(${v.x}, ${v.y}) rotate(${v.rotation}, ${cx}, ${cy})`
          : `translate(${v.x}, ${v.y})`;
      g.setAttribute('transform', transform);

      if (v.category === 'frame') {
        g.setAttribute('pointer-events', 'none');
      }

      const { d, mode } = buildStencilPath(v.stencilId, v.width, v.height, v.flipH);

      const hasFill =
        mode === 'fillstroke' &&
        v.fillColor !== 'none' &&
        v.fillOpacity > 0;
      const hasStroke =
        v.strokeColor !== 'none' &&
        v.strokeColor.toLowerCase() !== '#ffffff' &&
        v.strokeWidth > 0 &&
        v.strokeOpacity > 0;

      if (hasFill || hasStroke) {
        const path = document.createElementNS(SVG_NS, 'path');
        path.setAttribute('d', d);
        path.setAttribute('class', 'wan-shape-path');

        if (hasFill) {
          const gradKey = `${v.fillColor}_${v.gradientColor}_${v.gradientDirection}`;
          const gradId = gradientMap.get(gradKey);
          path.setAttribute('fill', gradId ? `url(#${gradId})` : v.fillColor);
          if (v.fillOpacity < 1) {
            path.setAttribute('fill-opacity', String(v.fillOpacity));
          }
        } else {
          path.setAttribute('fill', 'none');
        }

        if (hasStroke) {
          path.setAttribute('stroke', v.strokeColor);
          path.setAttribute('stroke-width', String(v.strokeWidth));
          if (v.strokeOpacity < 1) {
            path.setAttribute('stroke-opacity', String(v.strokeOpacity));
          }
          if (v.dashed) {
            path.setAttribute('stroke-dasharray', '9,6');
          }
        } else {
          path.setAttribute('stroke', 'none');
        }

        if (v.category === 'boundary' || v.id === '2') {
          path.setAttribute('pointer-events', 'stroke');
        }

        g.appendChild(path);
      } else if (v.lines.length > 0 && v.category !== 'frame') {
        // Invisible hit rect for pure text nodes (like Station headers) so they can be clicked easily
        const hitRect = document.createElementNS(SVG_NS, 'rect');
        hitRect.setAttribute('x', '0');
        hitRect.setAttribute('y', '0');
        hitRect.setAttribute('width', String(v.width));
        hitRect.setAttribute('height', String(v.height));
        hitRect.setAttribute('fill', 'transparent');
        hitRect.setAttribute('class', 'wan-hit-rect');
        g.appendChild(hitRect);
      }

      if (v.lines.length > 0) {
        const textGroup = createTextGroup(v.lines, v.width, v.height);
        g.appendChild(textGroup);
      }

      if (v.category === 'boundary') {
        boundaryElements.push(g);
      }

      viewportGroup.appendChild(g);
      elementMap.set(v.id, g);
    } else {
      const e = entry.item;
      const g = document.createElementNS(SVG_NS, 'g');
      g.setAttribute('class', `wan-element wan-edge cat-${e.category}`);
      g.setAttribute('data-id', e.id);
      g.setAttribute('data-kind', 'edge');
      g.setAttribute('data-category', e.category);
      g.setAttribute('data-region', e.region);

      // Wide transparent hit line for easy hovering/clicking
      const hitLine = document.createElementNS(SVG_NS, 'line');
      hitLine.setAttribute('x1', String(e.sourceX));
      hitLine.setAttribute('y1', String(e.sourceY));
      hitLine.setAttribute('x2', String(e.targetX));
      hitLine.setAttribute('y2', String(e.targetY));
      hitLine.setAttribute('stroke', 'transparent');
      hitLine.setAttribute('stroke-width', '14');
      hitLine.setAttribute('class', 'wan-edge-hit');
      g.appendChild(hitLine);

      // Visible optical/electrical line
      const line = document.createElementNS(SVG_NS, 'line');
      line.setAttribute('x1', String(e.sourceX));
      line.setAttribute('y1', String(e.sourceY));
      line.setAttribute('x2', String(e.targetX));
      line.setAttribute('y2', String(e.targetY));
      line.setAttribute('stroke', e.strokeColor);
      line.setAttribute('stroke-width', String(e.strokeWidth));
      line.setAttribute('stroke-linecap', 'round');
      line.setAttribute('class', 'wan-edge-line');
      if (e.dashed) {
        line.setAttribute('stroke-dasharray', '9,6');
      }
      g.appendChild(line);

      if (e.startArrow) {
        const startPoly = createArrowPolygon(
          e.sourceX,
          e.sourceY,
          e.targetX,
          e.targetY,
          e.strokeColor,
          e.strokeWidth
        );
        if (startPoly) g.appendChild(startPoly);
      }

      if (e.endArrow) {
        const endPoly = createArrowPolygon(
          e.targetX,
          e.targetY,
          e.sourceX,
          e.sourceY,
          e.strokeColor,
          e.strokeWidth
        );
        if (endPoly) g.appendChild(endPoly);
      }

      // Edge label centered on midpoint
      if (e.labelLines.length > 0) {
        const midX = (e.sourceX + e.targetX) / 2 + e.labelOffsetX;
        const midY = (e.sourceY + e.targetY) / 2 + e.labelOffsetY;

        const lblGroup = document.createElementNS(SVG_NS, 'g');
        lblGroup.setAttribute('class', 'wan-edge-label');
        const rotTransform =
          e.labelRotation !== 0
            ? `translate(${midX.toFixed(2)}, ${midY.toFixed(2)}) rotate(${e.labelRotation})`
            : `translate(${midX.toFixed(2)}, ${midY.toFixed(2)})`;
        lblGroup.setAttribute('transform', rotTransform);

        // Estimate label box dimensions for clean white background pill
        let maxW = 20;
        let totalH = 0;
        for (const l of e.labelLines) {
          const lineText = l.runs.map((r) => r.text).join('');
          const maxFs = Math.max(...l.runs.map((r) => r.fontSize), 12);
          const estW = lineText.length * maxFs * 0.52 + 10;
          if (estW > maxW) maxW = estW;
          totalH += maxFs * 1.18;
        }
        totalH += 4;

        if (e.labelBgColor && e.labelBgColor.toLowerCase() !== 'none') {
          const bgRect = document.createElementNS(SVG_NS, 'rect');
          bgRect.setAttribute('x', (-maxW / 2).toFixed(2));
          bgRect.setAttribute('y', (-totalH / 2).toFixed(2));
          bgRect.setAttribute('width', maxW.toFixed(2));
          bgRect.setAttribute('height', totalH.toFixed(2));
          bgRect.setAttribute('rx', '3');
          bgRect.setAttribute('fill', '#ffffff');
          bgRect.setAttribute('fill-opacity', '0.92');
          lblGroup.appendChild(bgRect);
        }

        const innerText = createTextGroup(e.labelLines, 0, 0);
        lblGroup.appendChild(innerText);

        g.appendChild(lblGroup);
        edgeLabelElements.push(lblGroup);
      }

      viewportGroup.appendChild(g);
      elementMap.set(e.id, g);
    }
  }

  svg.appendChild(viewportGroup);
  return { elementMap, boundaryElements, edgeLabelElements };
}



// --- src/ui/ganttModal.ts ---
class GanttModal {
          container             ;
          modalOverlay                     = null;
          activeSheetKey         = 'BQLDA';
          searchQuery         = '';
          selectedPhase         = 'ALL';
          viewMode                                 = 'split';

  constructor(container             ) {
    this.container = container;
  }

         open(initialSheetKey         = 'BQLDA')       {
    if (GANTT_DATA[initialSheetKey]) {
      this.activeSheetKey = initialSheetKey;
    }
    this.viewMode = window.innerWidth <= 768 ? 'table' : 'split';
    this.render();
  }

         close()       {
    if (this.modalOverlay) {
      this.modalOverlay.classList.remove('open');
      setTimeout(() => {
        this.modalOverlay?.remove();
        this.modalOverlay = null;
      }, 200);
    }
  }

          render()       {
    if (!this.modalOverlay) {
      this.modalOverlay = document.createElement('div');
      this.modalOverlay.className = 'wan-gantt-overlay';
      this.container.appendChild(this.modalOverlay);
    }

    const sheetKeys = Object.keys(GANTT_DATA);
    const currentSheet = GANTT_DATA[this.activeSheetKey] || GANTT_DATA['BQLDA'];

    this.modalOverlay.innerHTML = `
      <div class="wan-gantt-modal" role="dialog" aria-modal="true" aria-labelledby="gantt-modal-title">
        <!-- Header -->
        <div class="wan-gantt-header" style="background: #29348f;">
          <div class="wan-gantt-brand">
            <div class="wan-gantt-badge">TIẾN ĐỘ CẤP 3</div>
            <div>
              <h2 id="gantt-modal-title">KẾ HOẠCH TRIỂN KHAI DỰ ÁN MẠNG WAN EVNGENCO2</h2>
              <div class="wan-gantt-subtitle">${currentSheet.title} &bull; ${currentSheet.tasks.length} hạng mục</div>
            </div>
          </div>
          <button id="btn-close-gantt" class="wan-gantt-close-btn" title="Đóng bảng tiến độ (Phím Esc)">&times;</button>
        </div>

        <!-- Sheet Tabs -->
        <div class="wan-gantt-tabs">
          ${sheetKeys
            .map(
              (key) => `
            <button class="wan-gantt-tab-btn ${key === this.activeSheetKey ? 'active' : ''}" data-sheet="${key}">
              <span>${key}</span>
              <small class="wan-gantt-tab-count">${GANTT_DATA[key].tasks.length}</small>
            </button>
          `
            )
            .join('')}
        </div>

        <!-- Filter và Search Toolbar -->
        <div class="wan-gantt-toolbar">
          <div class="wan-gantt-search">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <circle cx="11" cy="11" r="8"/>
              <line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
            <input
              id="gantt-search-input"
              type="text"
              placeholder="Tìm theo STT, tên công việc, đơn vị thực hiện..."
              value="${this.searchQuery}"
              autocomplete="off"
            />
            ${this.searchQuery ? '<button id="gantt-search-clear">&times;</button>' : ''}
          </div>

          <!-- View Mode Toggle -->
          <div class="wan-gantt-view-toggle" id="gantt-view-toggle">
            <button class="wan-gantt-view-btn ${this.viewMode === 'table' ? 'active' : ''}" data-view="table" title="Chỉ xem bảng danh sách công việc">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 3H5a2 2 0 0 0-2 2v4m6-6h10a2 2 0 0 1 2 2v4M9 3v18m0 0h10a2 2 0 0 0 2-2V9M9 21H5a2 2 0 0 1-2-2V9m0 0h18"/></svg>
              <span>Danh sách</span>
            </button>
            <button class="wan-gantt-view-btn ${this.viewMode === 'timeline' ? 'active' : ''}" data-view="timeline" title="Chỉ xem biểu đồ tiến độ Gantt">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
              <span>Biểu đồ</span>
            </button>
            <button class="wan-gantt-view-btn ${this.viewMode === 'split' ? 'active' : ''}" data-view="split" title="Xem song song danh sách và biểu đồ">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M12 3v18"/></svg>
              <span>Cả hai</span>
            </button>
          </div>

          <div class="wan-gantt-phase-filters">
            <span class="wan-gantt-filter-label">Giai đoạn:</span>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'ALL' ? 'active' : ''}" data-phase="ALL">Tất cả</button>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'A' ? 'active' : ''}" data-phase="A">GĐ A (Khảo sát/TK)</button>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'B' ? 'active' : ''}" data-phase="B">GĐ B (Mua sắm)</button>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'C' ? 'active' : ''}" data-phase="C">GĐ C (Lắp đặt/VHT)</button>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'D' ? 'active' : ''}" data-phase="D">GĐ D (Bàn giao)</button>
            <button class="wan-gantt-filter-pill ${this.selectedPhase === 'E' || this.selectedPhase === 'F' ? 'active' : ''}" data-phase="E">GĐ E-F (Quyết toán)</button>
          </div>

          <div class="wan-gantt-stats-info" id="gantt-stats-info"></div>
        </div>

        <!-- Main Gantt Viewport -->
        <div class="wan-gantt-body" id="wan-gantt-body"></div>
      </div>
    `;

    // Trigger open animation
    requestAnimationFrame(() => {
      this.modalOverlay?.classList.add('open');
    });

    this.bindEvents();
    this.renderGanttChart();
  }

          bindEvents()       {
    if (!this.modalOverlay) return;

    // Close button
    this.modalOverlay.querySelector('#btn-close-gantt')?.addEventListener('click', () => {
      this.close();
    });

    // Close on backdrop click
    this.modalOverlay.addEventListener('click', (e) => {
      if (e.target === this.modalOverlay) {
        this.close();
      }
    });

    // Close on Escape key
    const onKeyDown = (e               ) => {
      if (e.key === 'Escape') {
        this.close();
        window.removeEventListener('keydown', onKeyDown);
      }
    };
    window.addEventListener('keydown', onKeyDown);

    // Sheet tabs
    const tabBtns = this.modalOverlay.querySelectorAll('.wan-gantt-tab-btn');
    tabBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = (btn               ).dataset.sheet;
        if (key && key !== this.activeSheetKey) {
          this.activeSheetKey = key;
          this.searchQuery = '';
          this.selectedPhase = 'ALL';
          this.render();
        }
      });
    });

    // Search input
    const searchInput = this.modalOverlay.querySelector('#gantt-search-input')                           ;
    searchInput?.addEventListener('input', () => {
      this.searchQuery = searchInput.value.trim().toLowerCase();
      this.renderGanttChart();
    });

    this.modalOverlay.querySelector('#gantt-search-clear')?.addEventListener('click', () => {
      this.searchQuery = '';
      if (searchInput) searchInput.value = '';
      this.render();
    });

    // Phase filters
    const filterPills = this.modalOverlay.querySelectorAll('.wan-gantt-filter-pill');
    filterPills.forEach((pill) => {
      pill.addEventListener('click', () => {
        const ph = (pill               ).dataset.phase || 'ALL';
        this.selectedPhase = ph;
        filterPills.forEach((p) => p.classList.toggle('active', p === pill));
        this.renderGanttChart();
      });
    });

    // View mode toggle
    const viewBtns = this.modalOverlay.querySelectorAll('.wan-gantt-view-btn');
    viewBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const mode = (btn               ).dataset.view                                  ;
        this.viewMode = mode;
        viewBtns.forEach((b) => b.classList.toggle('active', b === btn));
        const splitEl = this.modalOverlay?.querySelector('.wan-gantt-split');
        if (splitEl) {
          splitEl.classList.remove('view-split', 'view-table', 'view-timeline');
          splitEl.classList.add(`view-${mode}`);
        }
        if (mode === 'timeline') {
          const timelinePane = this.modalOverlay?.querySelector('#gantt-timeline-pane')                      ;
          const pin = timelinePane?.querySelector('.wan-realtime-header-pin')                      ;
          if (timelinePane && pin) {
            const left = parseFloat(pin.style.left) || 0;
            timelinePane.scrollLeft = Math.max(0, left - timelinePane.clientWidth / 2);
          }
        }
      });
    });
  }

          renderGanttChart()       {
    if (!this.modalOverlay) return;
    const bodyContainer = this.modalOverlay.querySelector('#wan-gantt-body')                      ;
    if (!bodyContainer) return;

    const sheet = GANTT_DATA[this.activeSheetKey];
    if (!sheet) return;

    // Filter tasks
    let filtered = sheet.tasks.filter((t) => {
      if (this.selectedPhase !== 'ALL') {
        if (this.selectedPhase === 'E') {
          if (t.phase !== 'E' && t.phase !== 'F') return false;
        } else if (t.phase !== this.selectedPhase && t.stt !== this.selectedPhase) {
          return false;
        }
      }
      if (this.searchQuery) {
        const matchName = t.name.toLowerCase().includes(this.searchQuery);
        const matchStt = t.stt.toLowerCase().includes(this.searchQuery);
        const matchUnit = t.unit.toLowerCase().includes(this.searchQuery);
        return matchName || matchStt || matchUnit;
      }
      return true;
    });

    // Current real-time timestamp
    const now = new Date();
    const nowMs = now.getTime();

    // Helper: Check if real time is within task start and end
    const isTaskActiveNow = (t           )          => {
      if (!t.start) return false;
      const sMs = new Date(t.start).getTime();
      if (isNaN(sMs)) return false;
      const eMs = t.end ? new Date(t.end).getTime() + 86400000 - 1 : sMs + 86400000 - 1;
      if (isNaN(eMs)) return false;
      return nowMs >= sMs && nowMs <= eMs;
    };

    // Update stats info
    const activeCount = filtered.filter((t) => isTaskActiveNow(t) && !t.isGroup && t.level > 0).length;
    const statsEl = this.modalOverlay.querySelector('#gantt-stats-info');
    if (statsEl) {
      statsEl.innerHTML = `Hiển thị <strong>${filtered.length}</strong> / ${sheet.tasks.length} hạng mục &bull; <span class="wan-gantt-active-stat"><strong>${activeCount}</strong> đang thực hiện</span>`;
    }

    if (filtered.length === 0) {
      bodyContainer.innerHTML = `
        <div class="wan-gantt-empty">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="1.5">
            <circle cx="11" cy="11" r="8"/>
            <line x1="21" y1="21" x2="16.65" y2="16.65"/>
          </svg>
          <p>Không tìm thấy hạng mục công việc phù hợp với từ khóa "${this.searchQuery}".</p>
        </div>
      `;
      return;
    }

    // Determine min and max dates for the timeline
    let minDateMs = Infinity;
    let maxDateMs = -Infinity;

    for (const t of sheet.tasks) {
      if (t.start) {
        const ms = new Date(t.start).getTime();
        if (ms < minDateMs) minDateMs = ms;
      }
      if (t.end) {
        const ms = new Date(t.end).getTime();
        if (ms > maxDateMs) maxDateMs = ms;
      }
    }

    // Fallback if no dates
    if (minDateMs === Infinity || maxDateMs === -Infinity) {
      minDateMs = new Date('2026-05-01').getTime();
      maxDateMs = new Date('2028-03-31').getTime();
    } else {
      // Pad by 15 days on each side
      minDateMs -= 15 * 86400000;
      maxDateMs += 20 * 86400000;
    }

    // Ensure minDateMs <= nowMs and maxDateMs >= nowMs so real time is always included in the timeline
    if (minDateMs > nowMs) minDateMs = nowMs - 15 * 86400000;
    if (maxDateMs < nowMs) maxDateMs = nowMs + 20 * 86400000;

    // Generate Month timeline slots
    const startObj = new Date(minDateMs);
    const endObj = new Date(maxDateMs);
    const months                                                                                                       = [];

    const cur = new Date(startObj.getFullYear(), startObj.getMonth(), 1);
    const endBoundary = new Date(endObj.getFullYear(), endObj.getMonth() + 1, 1);

    while (cur < endBoundary) {
      const y = cur.getFullYear();
      const m = cur.getMonth() + 1;
      const mStart = new Date(y, m - 1, 1).getTime();
      const mEnd = new Date(y, m, 1).getTime();
      const isCurrentMonth = y === now.getFullYear() && m === (now.getMonth() + 1);
      months.push({
        label: `T${m < 10 ? '0' + m : m}/${String(y).slice(2)}`,
        year: y,
        month: m,
        startMs: mStart,
        endMs: mEnd,
        isCurrent: isCurrentMonth,
      });
      cur.setMonth(cur.getMonth() + 1);
    }

    const MONTH_COL_WIDTH = 70;
    const totalTimelineWidth = months.length * MONTH_COL_WIDTH;
    const timelineStartMs = months[0].startMs;
    const timelineEndMs = months[months.length - 1].endMs;
    const totalDurationMs = timelineEndMs - timelineStartMs;

    // Real-time line and header pin calculation
    let realtimeLineHtml = '';
    let realtimeHeaderPinHtml = '';
    let nowLeftPx = -1;

    if (nowMs >= timelineStartMs && nowMs <= timelineEndMs) {
      const nowLeftPct = ((nowMs - timelineStartMs) / totalDurationMs) * 100;
      nowLeftPx = (nowLeftPct / 100) * totalTimelineWidth;

      const todayDay = String(now.getDate()).padStart(2, '0');
      const todayMonth = String(now.getMonth() + 1).padStart(2, '0');
      const todayYear = now.getFullYear();
      const formattedToday = `${todayDay}/${todayMonth}/${todayYear}`;

      realtimeHeaderPinHtml = `
        <div class="wan-realtime-header-pin" style="left: ${nowLeftPx.toFixed(1)}px;" title="Thời gian thực: ${formattedToday}"></div>
      `;

      realtimeLineHtml = `
        <div class="wan-realtime-line" style="left: ${nowLeftPx.toFixed(1)}px;" title="Đường thời gian thực: ${formattedToday}">
          <div class="wan-realtime-badge">
            <span class="wan-realtime-dot"></span>
            <span class="wan-realtime-label">Thời gian thực: ${formattedToday}</span>
          </div>
        </div>
      `;
    }

    // Helper to format date
    const formatDate = (d               ) => {
      if (!d) return '-';
      const [y, m, day] = d.split('-');
      return `${day}/${m}/${y}`;
    };

    // Color helper
    const getPhaseColor = (phase        , isGroup         )         => {
      if (isGroup) return '#1e293b';
      switch (phase) {
        case 'A':
          return '#2563eb'; // Blue - Khảo sát / TK
        case 'B':
          return '#ea580c'; // Orange - Mua sắm
        case 'C':
          return '#059669'; // Green - Lắp đặt / VHT
        case 'D':
          return '#7c3aed'; // Purple - Bàn giao
        case 'E':
        case 'F':
          return '#db2777'; // Pink - Quyết toán
        default:
          return '#0284c7';
      }
    };

    // Build Table Rows và Timeline Rows
    let tableRowsHtml = '';
    let timelineRowsHtml = '';

    filtered.forEach((t) => {
      const isActive = isTaskActiveNow(t);
      const isGroup = t.isGroup || t.level === 0;
      let rowClass = isGroup ? 'wan-gantt-row group' : 'wan-gantt-row';
      if (isActive) {
        rowClass += ' is-now-active';
      }
      const indentPx = Math.min(t.level, 3) * 16;

      // Table Row
      tableRowsHtml += `
        <div class="${rowClass}" data-task-id="${t.id}">
          <div class="wan-col-stt">${t.stt}</div>
          <div class="wan-col-name" style="padding-left: ${indentPx + 8}px;">
            <div class="wan-col-name-scroll">
              <span class="wan-task-title" title="${t.name}">${t.name}</span>
            </div>
            ${isActive && !isGroup ? '<span class="wan-tag-active-now" title="Công việc đang diễn ra trong thời gian thực">Đang thực hiện</span>' : ''}
          </div>
          <div class="wan-col-days">${t.days !== null ? `${t.days} ng` : '-'}</div>
          <div class="wan-col-start">${formatDate(t.start)}</div>
          <div class="wan-col-end">${formatDate(t.end)}</div>
          <div class="wan-col-unit" title="${t.unit}">
            <div class="wan-col-unit-scroll">
              <span class="wan-unit-title">${t.unit || '-'}</span>
            </div>
          </div>
        </div>
      `;

      // Timeline Row và Bar
      let barHtml = '';
      if (t.start && t.end) {
        const sMs = new Date(t.start).getTime();
        const eMs = new Date(t.end).getTime() + 86400000; // include end day
        const leftPct = Math.max(0, Math.min(100, ((sMs - timelineStartMs) / totalDurationMs) * 100));
        const rightPct = Math.max(0, Math.min(100, ((eMs - timelineStartMs) / totalDurationMs) * 100));
        const widthPct = Math.max(0.4, rightPct - leftPct);

        const color = getPhaseColor(t.phase, isGroup);
        const barClass = isGroup ? 'wan-gantt-bar is-group' : 'wan-gantt-bar';

        barHtml = `
          <div class="${barClass}" style="left: ${leftPct.toFixed(2)}%; width: ${widthPct.toFixed(2)}%; background-color: ${color};"
               data-tip-stt="${t.stt}"
               data-tip-name="${t.name}"
               data-tip-start="${formatDate(t.start)}"
               data-tip-end="${formatDate(t.end)}"
               data-tip-days="${t.days ?? '-'}"
               data-tip-unit="${t.unit}"
               data-tip-coord="${t.coord}">
            <span class="wan-bar-label">${t.days ? `${t.days}d` : ''}</span>
          </div>
        `;
      }

      timelineRowsHtml += `
        <div class="${rowClass} wan-timeline-row" data-task-id="${t.id}">
          ${barHtml}
        </div>
      `;
    });

    // Month headers và grid
    const monthHeadersHtml = months
      .map(
        (m) => `
      <div class="wan-gantt-month-col ${m.isCurrent ? 'is-current-month' : ''}" style="width: ${MONTH_COL_WIDTH}px;" title="${m.isCurrent ? 'Tháng hiện tại theo thời gian thực' : ''}">
        <span class="wan-month-name">${m.label}</span>
        ${m.isCurrent ? '<span class="wan-month-now-tag">Hiện tại</span>' : ''}
      </div>
    `
      )
      .join('');

    bodyContainer.innerHTML = `
      <div class="wan-gantt-split view-${this.viewMode}">
        <!-- Left Table -->
        <div class="wan-gantt-table-pane">
          <div class="wan-gantt-table-header">
            <div class="wan-col-stt">STT</div>
            <div class="wan-col-name">
              <div class="wan-col-name-scroll">
                <span class="wan-task-title" title="Nội dung công việc">Nội dung công việc</span>
              </div>
            </div>
            <div class="wan-col-days">Thời gian</div>
            <div class="wan-col-start">Bắt đầu</div>
            <div class="wan-col-end">Kết thúc</div>
            <div class="wan-col-unit">
              <div class="wan-col-unit-scroll">
                <span class="wan-unit-title" title="Đơn vị">Đơn vị</span>
              </div>
            </div>
          </div>
          <div class="wan-gantt-table-body" id="gantt-table-body">
            ${tableRowsHtml}
          </div>
        </div>

        <!-- Right Timeline -->
        <div class="wan-gantt-timeline-pane" id="gantt-timeline-pane">
          <div class="wan-gantt-timeline-header" style="width: ${totalTimelineWidth}px;">
            ${monthHeadersHtml}
            ${realtimeHeaderPinHtml}
          </div>
          <div class="wan-gantt-timeline-body" id="gantt-timeline-body" style="width: ${totalTimelineWidth}px;">
            <!-- Background vertical grid lines -->
            <div class="wan-timeline-grid-bg">
              ${months
                .map(
                  (m) => `
                <div class="wan-grid-month-line ${m.isCurrent ? 'is-current-month' : ''}" style="width: ${MONTH_COL_WIDTH}px;"></div>
              `
                )
                .join('')}
            </div>
            ${realtimeLineHtml}
            ${timelineRowsHtml}
          </div>
        </div>
      </div>

      <!-- Gantt Bar Floating Tooltip -->
      <div id="gantt-tooltip" class="wan-gantt-tooltip hidden"></div>
    `;

    // Query elements
    const tableBody = bodyContainer.querySelector('#gantt-table-body')                      ;
    const timelinePane = bodyContainer.querySelector('#gantt-timeline-pane')                      ;

    // Auto-scroll timeline to real-time position so today is immediately visible
    if (nowLeftPx > 0 && timelinePane) {
      requestAnimationFrame(() => {
        timelinePane.scrollLeft = Math.max(0, nowLeftPx - timelinePane.clientWidth / 2);
      });
    }

    // Auto-scroll table to the first active task on initial view
    if (!this.searchQuery && tableBody) {
      const firstActiveRow = tableBody.querySelector('.wan-gantt-row.is-now-active')                      ;
      if (firstActiveRow) {
        requestAnimationFrame(() => {
          tableBody.scrollTop = Math.max(0, firstActiveRow.offsetTop - 80);
        });
      }
    }

    // Synchronize vertical scrolling between Table and Timeline
    let isSyncing = false;
    if (tableBody && timelinePane) {
      tableBody.addEventListener('scroll', () => {
        if (!isSyncing) {
          isSyncing = true;
          timelinePane.scrollTop = tableBody.scrollTop;
          isSyncing = false;
        }
      });

      timelinePane.addEventListener('scroll', () => {
        if (!isSyncing) {
          isSyncing = true;
          tableBody.scrollTop = timelinePane.scrollTop;
          isSyncing = false;
        }
      });
    }

    // Attach Bar Hover & Tap Tooltip
    const tooltip = bodyContainer.querySelector('#gantt-tooltip')                      ;
    if (tooltip) {
      const bars = bodyContainer.querySelectorAll('.wan-gantt-bar');
      const showTooltip = (el             ) => {
        const stt = el.dataset.tipStt || '';
        const name = el.dataset.tipName || '';
        const start = el.dataset.tipStart || '';
        const end = el.dataset.tipEnd || '';
        const days = el.dataset.tipDays || '';
        const unit = el.dataset.tipUnit || '';
        const coord = el.dataset.tipCoord || '';

        tooltip.innerHTML = `
          <div class="wan-gtip-title">${stt ? `[${stt}] ` : ''}${name}</div>
          <div class="wan-gtip-row"><span>Thời gian:</span> <strong>${start} &rarr; ${end} (${days} ngày)</strong></div>
          ${unit ? `<div class="wan-gtip-row"><span>Đơn vị thực hiện:</span> <strong>${unit}</strong></div>` : ''}
          ${coord ? `<div class="wan-gtip-row"><span>Phối hợp:</span> <strong>${coord}</strong></div>` : ''}
        `;
        tooltip.classList.remove('hidden');

        const rect = el.getBoundingClientRect();
        const center = rect.left + rect.width / 2;
        const clampedLeft = Math.max(160, Math.min(window.innerWidth - 160, center));
        tooltip.style.left = `${clampedLeft}px`;
        const clampedTop = Math.max(50, rect.top - 8);
        tooltip.style.top = `${clampedTop}px`;
      };

      bars.forEach((bar) => {
        const el = bar               ;
        bar.addEventListener('mouseenter', () => showTooltip(el));
        bar.addEventListener('click', (e) => {
          e.stopPropagation();
          showTooltip(el);
        });
        bar.addEventListener('mouseleave', () => {
          tooltip.classList.add('hidden');
        });
      });

      bodyContainer.addEventListener('click', (e) => {
        if (!(e.target           )?.closest?.('.wan-gantt-bar')) {
          tooltip.classList.add('hidden');
        }
      });
    }

    // Highlight row on hover
    const rows = bodyContainer.querySelectorAll('.wan-gantt-row');
    rows.forEach((row) => {
      row.addEventListener('mouseenter', () => {
        const id = (row               ).dataset.taskId;
        if (id) {
          bodyContainer.querySelectorAll(`[data-task-id="${id}"]`).forEach((r) => r.classList.add('hover'));
        }
      });
      row.addEventListener('mouseleave', () => {
        const id = (row               ).dataset.taskId;
        if (id) {
          bodyContainer.querySelectorAll(`[data-task-id="${id}"]`).forEach((r) => r.classList.remove('hover'));
        }
      });
    });

    // Hiệu ứng hover di chuyển hiển thị đầy đủ nội dung cho cột Nội dung và Đơn vị
    this.setupTableMarquee(bodyContainer);
  }

          setupTableMarquee(container             )       {
    const scrollCells = container.querySelectorAll             ('.wan-col-name, .wan-col-unit');
    scrollCells.forEach((cell) => {
      cell.addEventListener('mouseenter', () => {
        const textSpan = cell.querySelector             ('.wan-task-title, .wan-unit-title');
        const scrollWrap = cell.querySelector             ('.wan-col-name-scroll, .wan-col-unit-scroll');
        if (!textSpan || !scrollWrap) return;

        // Tính toán độ chênh lệch giữa toàn bộ chiều dài nội dung và khung nhìn thấy
        const wrapWidth = scrollWrap.clientWidth;
        const textWidth = textSpan.scrollWidth;
        const diff = textWidth - wrapWidth;

        if (diff > 4) {
          textSpan.classList.add('is-overflowing');
          textSpan.style.setProperty('--marquee-distance', `-${Math.ceil(diff + 16)}px`);
          const duration = Math.max(3, Math.min(12, Math.ceil(diff / 40) + 1.5));
          textSpan.style.setProperty('--marquee-duration', `${duration}s`);
        } else {
          textSpan.classList.remove('is-overflowing');
        }
      });

      cell.addEventListener('mouseleave', () => {
        const textSpan = cell.querySelector             ('.wan-task-title, .wan-unit-title');
        if (textSpan) {
          textSpan.style.transform = '';
        }
      });
    });
  }
}


// --- src/ui/bangthongModal.ts ---
class BangThongModal {
          container             ;
          modalOverlay                     = null;
          searchQuery         = '';
          filterSpeed         = 'ALL';

  constructor(container             ) {
    this.container = container;
  }

         open()       {
    this.searchQuery = '';
    this.filterSpeed = 'ALL';
    this.render();
  }

         close()       {
    if (this.modalOverlay) {
      this.modalOverlay.classList.remove('open');
      setTimeout(() => {
        this.modalOverlay?.remove();
        this.modalOverlay = null;
      }, 200);
    }
  }

          getBadgeClass(speed        )         {
    const s = speed.trim().toLowerCase();
    if (s.includes('10 gbps')) return 'wan-bt-badge-10g';
    if (s.includes('1 gbps')) return 'wan-bt-badge-1g';
    if (s.includes('622 mbps')) return 'wan-bt-badge-622m';
    if (s.includes('155 mbps')) return 'wan-bt-badge-155m';
    if (s.includes('100 mbps')) return 'wan-bt-badge-100m';
    return 'wan-bt-badge-default';
  }

          filterData()                 {
    const q = this.searchQuery.trim().toLowerCase();
    const speed = this.filterSpeed;

    return BANG_THONG_DATA.filter((row) => {
      // Speed filter
      if (speed !== 'ALL') {
        const matchThucTe = row.bangThongThucTe.toLowerCase().includes(speed.toLowerCase());
        const matchToiDa = row.bangThongToiDa.toLowerCase().includes(speed.toLowerCase());
        if (!matchThucTe && !matchToiDa) return false;
      }

      // Search query
      if (!q) return true;
      return (
        row.stt.toLowerCase().includes(q) ||
        row.tuyenQuang.toLowerCase().includes(q) ||
        row.diemA_diemB.toLowerCase().includes(q) ||
        row.bangThongThucTe.toLowerCase().includes(q) ||
        row.bangThongToiDa.toLowerCase().includes(q) ||
        row.ghiChu.toLowerCase().includes(q)
      );
    });
  }

          render()       {
    if (!this.modalOverlay) {
      this.modalOverlay = document.createElement('div');
      this.modalOverlay.className = 'wan-gantt-overlay open';
      this.container.appendChild(this.modalOverlay);
    }

    const filteredRows = this.filterData();

    // Stats
    const totalLines = BANG_THONG_DATA.length;
    const max10G = BANG_THONG_DATA.filter((r) => r.bangThongToiDa.includes('10 Gbps')).length;
    const max1G = BANG_THONG_DATA.filter((r) => r.bangThongToiDa === '1 Gbps').length;
    const max622M = BANG_THONG_DATA.filter((r) => r.bangThongToiDa.includes('622 Mbps')).length;
    const hasNote = BANG_THONG_DATA.filter((r) => r.ghiChu.length > 0).length;

    let tableRowsHtml = '';
    let currentParentTuyen = '';

    filteredRows.forEach((item) => {
      const isSubBranch = !item.stt && !item.tuyenQuang;
      if (item.tuyenQuang) {
        currentParentTuyen = item.tuyenQuang;
      }

      const sttDisplay = item.stt || '<span class="wan-bt-sub-arrow">↳</span>';
      const tuyenDisplay = item.tuyenQuang
        ? `<strong class="wan-bt-parent-title">${item.tuyenQuang}</strong>`
        : `<span class="wan-bt-sub-hint">Nhánh thuộc: ${currentParentTuyen}</span>`;

      const badgeThucTe = `<span class="wan-bt-badge ${this.getBadgeClass(item.bangThongThucTe)}">${item.bangThongThucTe}</span>`;
      const badgeToiDa = `<span class="wan-bt-badge ${this.getBadgeClass(item.bangThongToiDa)}">${item.bangThongToiDa}</span>`;

      const ghiChuDisplay = item.ghiChu
        ? `<div class="wan-bt-note-box"><span class="wan-bt-note-icon">⚠️</span> ${item.ghiChu}</div>`
        : '<span class="wan-bt-text-muted">-</span>';

      tableRowsHtml += `
        <tr class="wan-bt-row ${isSubBranch ? 'wan-bt-row-sub' : ''} ${item.ghiChu ? 'has-note' : ''}">
          <td class="wan-bt-col-stt">${sttDisplay}</td>
          <td class="wan-bt-col-tuyen">${tuyenDisplay}</td>
          <td class="wan-bt-col-route">
            <div class="wan-bt-route-text">${item.diemA_diemB}</div>
          </td>
          <td class="wan-bt-col-speed-now">${badgeThucTe}</td>
          <td class="wan-bt-col-speed-max">${badgeToiDa}</td>
          <td class="wan-bt-col-note">${ghiChuDisplay}</td>
        </tr>
      `;
    });

    if (filteredRows.length === 0) {
      tableRowsHtml = `
        <tr>
          <td colspan="6" class="wan-bt-empty">
            Không tìm thấy tuyến quang nào khớp với từ khóa "<strong>${this.searchQuery}</strong>".
          </td>
        </tr>
      `;
    }

    this.modalOverlay.innerHTML = `
      <div class="wan-gantt-modal wan-bangthong-modal" role="dialog" aria-modal="true" aria-labelledby="bt-modal-title">
        <!-- Header -->
        <div class="wan-gantt-header" style="background: #1e3a8a;">
          <div class="wan-gantt-brand">
            <div class="wan-gantt-badge" style="background: transparent; border: none;">BĂNG THÔNG DỰ ÁN</div>
            <div>
              <h2 id="bt-modal-title">THÔNG TIN BĂNG THÔNG CÁC TUYẾN QUANG DỰ ÁN WAN EVNGENCO2</h2>
            </div>
          </div>
          <div style="display:flex; align-items:center; gap:8px;">
            <a href="bangthong.xlsx" download="bangthong.xlsx" class="wan-bt-download-btn" title="Tải xuống file gốc bangthong.xlsx">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
                <polyline points="7 10 12 15 17 10"></polyline>
                <line x1="12" y1="15" x2="12" y2="3"></line>
              </svg>
              Tải file Excel
            </a>
            <button id="btn-close-bangthong" class="wan-gantt-close-btn" title="Đóng bảng băng thông (Phím Esc)">&times;</button>
          </div>
        </div>

        <!-- KPI Stats Cards -->
        <div class="wan-bt-kpis">
          <div class="wan-bt-kpi-card">
            <span class="wan-bt-kpi-num">${totalLines}</span>
            <span class="wan-bt-kpi-label">Tổng số lộ tuyến</span>
          </div>
          <div class="wan-bt-kpi-card accent-10g">
            <span class="wan-bt-kpi-num">${max10G}</span>
            <span class="wan-bt-kpi-label">Hỗ trợ tối đa 10 Gbps</span>
          </div>
          <div class="wan-bt-kpi-card accent-1g">
            <span class="wan-bt-kpi-num">${max1G}</span>
            <span class="wan-bt-kpi-label">Hỗ trợ tối đa 1 Gbps</span>
          </div>
          <div class="wan-bt-kpi-card accent-622m">
            <span class="wan-bt-kpi-num">${max622M}</span>
            <span class="wan-bt-kpi-label">Hỗ trợ tối đa 622 Mbps</span>
          </div>
          <div class="wan-bt-kpi-card accent-warn">
            <span class="wan-bt-kpi-num">${hasNote}</span>
            <span class="wan-bt-kpi-label">Tuyến giới hạn hạ tầng</span>
          </div>
        </div>

        <!-- Filter & Search Toolbar -->
        <div class="wan-bt-toolbar">
          <div class="wan-bt-search-box">
            <svg class="wan-bt-search-icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <circle cx="11" cy="11" r="8"></circle>
              <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
            </svg>
            <input
              type="text"
              id="wan-bt-search-input"
              class="wan-bt-search-input"
              placeholder="Tìm kiếm theo trạm, lộ trình, điểm kết nối, ghi chú..."
              value="${this.searchQuery}"
            />
            ${this.searchQuery ? '<button id="btn-bt-clear-search" class="wan-bt-clear-search">&times;</button>' : ''}
          </div>

          <div class="wan-bt-speed-filter">
            <span class="wan-bt-filter-label">Lọc băng thông:</span>
            <button class="wan-bt-filter-btn ${this.filterSpeed === 'ALL' ? 'active' : ''}" data-speed="ALL">Tất cả</button>
            <button class="wan-bt-filter-btn ${this.filterSpeed === '10 Gbps' ? 'active' : ''}" data-speed="10 Gbps">10 Gbps</button>
            <button class="wan-bt-filter-btn ${this.filterSpeed === '1 Gbps' ? 'active' : ''}" data-speed="1 Gbps">1 Gbps</button>
            <button class="wan-bt-filter-btn ${this.filterSpeed === '622 Mbps' ? 'active' : ''}" data-speed="622 Mbps">622 Mbps</button>
            <button class="wan-bt-filter-btn ${this.filterSpeed === '100 Mbps' ? 'active' : ''}" data-speed="100 Mbps">100 Mbps</button>
          </div>
        </div>

        <!-- Table Container -->
        <div class="wan-bt-table-container">
          <table class="wan-bt-table">
            <thead>
              <tr>
                <th style="width: 50px; text-align: center;">STT</th>
                <th style="width: 250px;">Tuyến quang</th>
                <th>Điểm A &rarr; Điểm B (Lộ trình chi tiết)</th>
                <th style="width: 150px; text-align: center;">Băng thông thực tế</th>
                <th style="width: 170px; text-align: center;">Băng thông tối đa hỗ trợ</th>
                <th style="width: 280px;">Ghi chú hạ tầng</th>
              </tr>
            </thead>
            <tbody>
              ${tableRowsHtml}
            </tbody>
          </table>
        </div>

        <!-- Footer -->
        <div class="wan-bt-footer">
          <div class="wan-bt-footer-info">
            Đang hiển thị <strong>${filteredRows.length}/${totalLines}</strong> lộ tuyến quang &bull; Nhấn <kbd>Esc</kbd> hoặc dấu &times; để đóng
          </div>
          <button id="btn-bt-close-bottom" class="wan-tool-btn wan-btn-primary" style="padding: 6px 18px; font-size: 13px;">
            Đóng bảng
          </button>
        </div>
      </div>
    `;

    this.bindEvents();
  }

          bindEvents()       {
    if (!this.modalOverlay) return;

    // Close buttons
    const closeBtn = this.modalOverlay.querySelector('#btn-close-bangthong');
    const closeBottomBtn = this.modalOverlay.querySelector('#btn-bt-close-bottom');
    closeBtn?.addEventListener('click', () => this.close());
    closeBottomBtn?.addEventListener('click', () => this.close());

    // Click outside overlay to close
    this.modalOverlay.addEventListener('click', (e) => {
      if (e.target === this.modalOverlay) {
        this.close();
      }
    });

    // Esc key
    const onKey = (e               ) => {
      if (e.key === 'Escape') {
        this.close();
        document.removeEventListener('keydown', onKey);
      }
    };
    document.addEventListener('keydown', onKey);

    // Search input
    const searchInput = this.modalOverlay.querySelector('#wan-bt-search-input')                    ;
    searchInput?.addEventListener('input', (e) => {
      this.searchQuery = (e.target                    ).value;
      this.render();
      const updatedInput = this.modalOverlay?.querySelector('#wan-bt-search-input')                    ;
      if (updatedInput) {
        updatedInput.focus();
        updatedInput.setSelectionRange(this.searchQuery.length, this.searchQuery.length);
      }
    });

    // Clear search
    this.modalOverlay.querySelector('#btn-bt-clear-search')?.addEventListener('click', () => {
      this.searchQuery = '';
      this.render();
    });

    // Speed filter buttons
    const filterBtns = this.modalOverlay.querySelectorAll('.wan-bt-filter-btn');
    filterBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        this.filterSpeed = (btn               ).dataset.speed || 'ALL';
        this.render();
      });
    });
  }
}


// --- src/ui/authWidget.ts ---
const AUTH_STORAGE_KEY = 'wan_admin_session_v3';
// Băm SHA-256 an toàn của mã quản trị - Mật mã gốc không bao giờ xuất hiện ở dạng plaintext
const ADMIN_AUTH_HASH = '45b8778b307f91d4e32dd17b51b02f4b95ff5b7c10e66485b6275cdf294d3105';
async function hashSha256(message        )                  {
  const msgBuffer = new TextEncoder().encode(message.trim());
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
}
class AuthManager {
          static failedAttempts = 0;
          static lockedUntil = 0;

         static isAuthenticated()          {
    try {
      const raw = sessionStorage.getItem(AUTH_STORAGE_KEY) || localStorage.getItem(AUTH_STORAGE_KEY);
      if (!raw) return false;
      const session              = JSON.parse(raw);
      if (session && typeof session.expiresAt === 'number') {
        if (Date.now() > session.expiresAt) {
          this.logout();
          return false;
        }
        return Boolean(session.token);
      }
    } catch {
      return false;
    }
    return false;
  }

         static getAuthToken()                {
    try {
      const raw = sessionStorage.getItem(AUTH_STORAGE_KEY) || localStorage.getItem(AUTH_STORAGE_KEY);
      if (!raw) return null;
      const session              = JSON.parse(raw);
      if (session && session.token && Date.now() < session.expiresAt) {
        return session.token;
      }
    } catch {}
    return null;
  }

         static async login(code        )                                                {
    const trimmed = code.trim();
    if (!trimmed) {
      return { success: false, error: 'Vui lòng nhập mã đăng nhập!' };
    }

    // Kiểm tra giới hạn khóa tạm thời do nhập sai nhiều lần
    if (Date.now() < this.lockedUntil) {
      const waitSec = Math.ceil((this.lockedUntil - Date.now()) / 1000);
      return { success: false, error: `Tài khoản tạm khóa do nhập sai quá 5 lần. Vui lòng đợi ${waitSec} giây.` };
    }

    // 1. Xác thực qua Server API /api/auth
    try {
      const res = await fetch('/api/auth', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: trimmed }),
      });

      const data = await res.json();

      if (res.ok && data.success && data.token) {
        this.saveSession({
          token: data.token,
          expiresAt: data.expiresAt || Date.now() + 8 * 3600 * 1000,
        });
        this.failedAttempts = 0;
        window.dispatchEvent(new CustomEvent('wan:auth-changed', { detail: { isAuthenticated: true } }));
        return { success: true };
      }

      if (res.status === 429) {
        this.lockedUntil = Date.now() + 60 * 1000;
        return { success: false, error: data.error || 'Quá nhiều lần thử sai. Vui lòng thử lại sau 60 giây.' };
      }

      if (res.status === 401) {
        this.recordFailedAttempt();
        return { success: false, error: data.error || 'Mã đăng nhập không chính xác!' };
      }
    } catch {
      // 2. Chế độ dự phòng offline (so sánh SHA-256 an toàn bằng Web Crypto API)
      try {
        const hash = await hashSha256(trimmed);
        if (hash === ADMIN_AUTH_HASH) {
          const offlineToken = `off-${hash.slice(0, 16)}-${Date.now()}`;
          this.saveSession({
            token: offlineToken,
            expiresAt: Date.now() + 8 * 3600 * 1000,
          });
          this.failedAttempts = 0;
          window.dispatchEvent(new CustomEvent('wan:auth-changed', { detail: { isAuthenticated: true } }));
          return { success: true };
        }
      } catch {
        // Crypto API error
      }
    }

    this.recordFailedAttempt();
    return { success: false, error: 'Mã đăng nhập không chính xác!' };
  }

          static recordFailedAttempt()       {
    this.failedAttempts++;
    if (this.failedAttempts >= 5) {
      this.lockedUntil = Date.now() + 60 * 1000;
    }
  }

          static saveSession(session             )       {
    try {
      const str = JSON.stringify(session);
      sessionStorage.setItem(AUTH_STORAGE_KEY, str);
      localStorage.setItem(AUTH_STORAGE_KEY, str);
    } catch {}
  }

         static logout()       {
    try {
      sessionStorage.removeItem(AUTH_STORAGE_KEY);
      localStorage.removeItem(AUTH_STORAGE_KEY);
      sessionStorage.removeItem('wan_login_session');
      localStorage.removeItem('wan_login_session');
      localStorage.removeItem('wan_admin_auth_code'); // Dọn dẹp key cũ
    } catch {}
    window.dispatchEvent(new CustomEvent('wan:auth-changed', { detail: { isAuthenticated: false } }));
    window.dispatchEvent(new CustomEvent('wan:logout'));
  }
}
class AuthWidget {
          container             ;
          wrapperEl                     = null;
          isOpen          = false;

  constructor(container             ) {
    this.container = container;
  }

         mount()       {
    if (this.wrapperEl) return;

    this.wrapperEl = document.createElement('div');
    this.wrapperEl.className = 'wan-auth-widget-container';
    this.container.appendChild(this.wrapperEl);

    this.render();
    this.bindEvents();

    window.addEventListener('wan:auth-changed', () => {
      this.render();
    });
  }

          render()       {
    if (!this.wrapperEl) return;

    const isAuthed = AuthManager.isAuthenticated();

    this.wrapperEl.innerHTML = `
      <!-- Floating Tab Button on Right Middle -->
      <button id="wan-btn-auth-toggle" class="wan-auth-toggle-tab ${isAuthed ? 'is-authed' : ''}" title="${isAuthed ? 'Quản trị viên (Đã xác thực mã)' : 'Đăng nhập mã quản trị'}">
        <svg class="wan-auth-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          ${
            isAuthed
              ? `<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/>`
              : `<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>`
          }
        </svg>
        ${isAuthed ? '<span class="wan-auth-online-dot"></span>' : ''}
      </button>

      <!-- Flyout Login Popover (Appears beside icon) -->
      <div id="wan-auth-popover" class="wan-auth-popover ${this.isOpen ? 'open' : ''}">
        <div class="wan-auth-popover-header">
          <div class="wan-auth-popover-title">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
              <rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>
              <path d="M7 11V7a5 5 0 0 1 10 0v4"/>
            </svg>
            <span>${isAuthed ? 'Xác thực thành công' : 'Đăng nhập quản trị'}</span>
          </div>
          <button id="btn-close-auth-popover" class="wan-auth-close-btn">&times;</button>
        </div>

        <div class="wan-auth-popover-body">
          ${
            isAuthed
              ? `
            <div class="wan-auth-status-card">
              <div class="wan-auth-badge-success">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                  <polyline points="20 6 9 17 4 12"/>
                </svg>
                <span>Quyền: Quản trị viên</span>
              </div>
              <p class="wan-auth-desc">Bạn có quyền nhập và chỉnh sửa dữ liệu tại bảng <strong>Triển khai thực tế</strong>.</p>
              <button id="btn-auth-logout" class="wan-btn-auth-action danger">Đăng xuất</button>
            </div>
          `
              : `
            <div class="wan-auth-form">
              <label for="auth-input-code" class="wan-auth-label">Mã đăng nhập:</label>
              <div class="wan-auth-input-wrap">
                <input
                  id="auth-input-code"
                  type="password"
                  class="wan-auth-input"
                  placeholder="Nhập mã đăng nhập..."
                  autocomplete="off"
                />
                <button type="button" id="btn-toggle-show-pwd" class="wan-auth-eye-btn" title="Hiện/Ẩn mã">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                    <circle cx="12" cy="12" r="3"/>
                  </svg>
                </button>
              </div>
              <div id="auth-error-msg" class="wan-auth-error-msg hidden">Mã đăng nhập không chính xác!</div>
              <button id="btn-auth-submit" class="wan-btn-auth-action primary">Xác nhận</button>
            </div>
          `
          }
        </div>
      </div>
    `;
  }

          bindEvents()       {
    if (!this.wrapperEl) return;

    this.wrapperEl.addEventListener('click', (e) => {
      const target = e.target               ;

      // Toggle tab button
      if (target.closest('#wan-btn-auth-toggle')) {
        this.isOpen = !this.isOpen;
        this.render();
        if (this.isOpen) {
          setTimeout(() => {
            (this.wrapperEl?.querySelector('#auth-input-code')                           )?.focus();
          }, 100);
        }
        return;
      }

      // Close popover
      if (target.closest('#btn-close-auth-popover')) {
        this.isOpen = false;
        this.render();
        return;
      }

      // Logout button
      if (target.closest('#btn-auth-logout')) {
        AuthManager.logout();
        this.render();
        return;
      }

      // Toggle show/hide password
      if (target.closest('#btn-toggle-show-pwd')) {
        const input = this.wrapperEl?.querySelector('#auth-input-code')                           ;
        if (input) {
          input.type = input.type === 'password' ? 'text' : 'password';
        }
        return;
      }

      // Submit login
      if (target.closest('#btn-auth-submit')) {
        this.handleLoginSubmit();
      }
    });

    // Enter key to submit
    this.wrapperEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const input = this.wrapperEl?.querySelector('#auth-input-code')                           ;
        if (document.activeElement === input) {
          e.preventDefault();
          this.handleLoginSubmit();
        }
      }
      if (e.key === 'Escape' && this.isOpen) {
        this.isOpen = false;
        this.render();
      }
    });
  }

          async handleLoginSubmit()                {
    const input = this.wrapperEl?.querySelector('#auth-input-code')                           ;
    const errorMsg = this.wrapperEl?.querySelector('#auth-error-msg')                      ;
    const submitBtn = this.wrapperEl?.querySelector('#btn-auth-submit')                            ;
    if (!input) return;

    const val = input.value.trim();
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = 'Đang kiểm tra...';
    }

    try {
      const result = await AuthManager.login(val);
      if (result.success) {
        this.isOpen = false;
        this.render();
      } else {
        if (errorMsg) {
          errorMsg.textContent = result.error || 'Mã đăng nhập không chính xác!';
          errorMsg.classList.remove('hidden');
          input.classList.add('error');
          input.focus();
        }
      }
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Xác nhận';
      }
    }
  }
}



// --- src/ui/deploymentModal.ts ---


function escapeHtml(str     )         {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
class DeploymentModal {
          container             ;
          modalOverlay                     = null;
          isAddingRow          = false;
          editingId                = null;

  constructor(container             ) {
    this.container = container;
  }

         async open()                {
    if (!this.modalOverlay) {
      this.modalOverlay = document.createElement('div');
      this.modalOverlay.className = 'wan-deploy-overlay';
      this.container.appendChild(this.modalOverlay);

      // Listen for auth changes to re-render in real-time
      window.addEventListener('wan:auth-changed', () => {
        if (this.modalOverlay?.classList.contains('open')) {
          this.render();
        }
      });
    }

    this.isAddingRow = false;
    this.editingId = null;

    // Tải đồng bộ mới nhất từ server nếu có
    try {
      const res = await fetch('/api/baocao');
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data) && data.length > 0) {
          BaocaoStore.saveItems(data);
        }
      }
    } catch {
      // Giữ nguyên dữ liệu hiện tại
    }

    this.render();

    requestAnimationFrame(() => {
      this.modalOverlay?.classList.add('open');
    });
  }

         close()       {
    if (this.modalOverlay) {
      this.modalOverlay.classList.remove('open');
      setTimeout(() => {
        this.modalOverlay?.remove();
        this.modalOverlay = null;
      }, 200);
    }
  }

          getFormattedCurrentTime()         {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    return `${d}/${m}/${y}`;
  }

          render()       {
    if (!this.modalOverlay) return;

    const items = BaocaoStore.getItems();
    const isAuthed = AuthManager.isAuthenticated();

    let tableRowsHtml = '';

    // If currently adding a row, render the inline form at the top
    if (this.isAddingRow && isAuthed) {
      const defaultTime = this.getFormattedCurrentTime();
      tableRowsHtml += `
        <tr class="wan-deploy-row-edit adding-new">
          <td class="wan-dp-col-stt">Mới</td>
          <td class="wan-dp-col-time">
            <input id="input-new-time" type="text" class="wan-dp-input" value="${defaultTime}" placeholder="dd/mm/yyyy" />
          </td>
          <td class="wan-dp-col-content">
            <textarea id="input-new-content" class="wan-dp-textarea" placeholder="Nhập nội dung triển khai thực tế..." rows="1" autofocus></textarea>
          </td>
          <td class="wan-dp-col-status">
            <select id="select-new-status" class="wan-dp-select">
              <option value="Đang thực hiện">Đang thực hiện</option>
              <option value="Hoàn thành">Hoàn thành</option>
              <option value="Chờ xử lý">Chờ xử lý</option>
              <option value="Kế hoạch">Kế hoạch</option>
            </select>
          </td>
          <td class="wan-dp-col-action">
            <button id="btn-save-new-row" class="wan-dp-btn save" title="Lưu hàng mới">Lưu</button>
            <button id="btn-cancel-new-row" class="wan-dp-btn cancel" title="Hủy bỏ">Hủy</button>
          </td>
        </tr>
      `;
    }

    if (items.length === 0 && !this.isAddingRow) {
      tableRowsHtml = `
        <tr>
          <td colspan="${isAuthed ? 5 : 4}" class="wan-deploy-empty">Chưa có báo cáo triển khai thực tế nào.</td>
        </tr>
      `;
    } else {
      items.forEach((item, idx) => {
        const isEditing = this.editingId === item.id && isAuthed;

        if (isEditing) {
          tableRowsHtml += `
            <tr class="wan-deploy-row-edit" data-id="${item.id}">
              <td class="wan-dp-col-stt">${idx + 1}</td>
              <td class="wan-dp-col-time">
                <input id="edit-time-${item.id}" type="text" class="wan-dp-input" value="${escapeHtml(item.time)}" placeholder="dd/mm/yyyy" />
              </td>
              <td class="wan-dp-col-content">
                <textarea id="edit-content-${item.id}" class="wan-dp-textarea" placeholder="Nhập nội dung triển khai thực tế..." rows="1">${escapeHtml(item.content)}</textarea>
              </td>
              <td class="wan-dp-col-status">
                <select id="edit-status-${item.id}" class="wan-dp-select">
                  <option value="Đang thực hiện" ${item.status === 'Đang thực hiện' ? 'selected' : ''}>Đang thực hiện</option>
                  <option value="Hoàn thành" ${item.status === 'Hoàn thành' ? 'selected' : ''}>Hoàn thành</option>
                  <option value="Chờ xử lý" ${item.status === 'Chờ xử lý' ? 'selected' : ''}>Chờ xử lý</option>
                  <option value="Kế hoạch" ${item.status === 'Kế hoạch' ? 'selected' : ''}>Kế hoạch</option>
                </select>
              </td>
              <td class="wan-dp-col-action">
                <button class="wan-dp-btn save btn-save-edit" data-id="${item.id}" title="Lưu chỉnh sửa">Lưu</button>
                <button class="wan-dp-btn cancel btn-cancel-edit" data-id="${item.id}" title="Hủy bỏ">Hủy</button>
              </td>
            </tr>
          `;
        } else {
          const statusClass = item.status === 'Hoàn thành' ? 'badge-success' : 'badge-warning';
          tableRowsHtml += `
            <tr class="wan-deploy-row" data-id="${item.id}">
              <td class="wan-dp-col-stt">${idx + 1}</td>
              <td class="wan-dp-col-time"><strong>${escapeHtml(item.time)}</strong></td>
              <td class="wan-dp-col-content">${escapeHtml(item.content)}</td>
              <td class="wan-dp-col-status">
                <span class="wan-status-badge ${statusClass}">${escapeHtml(item.status)}</span>
              </td>
              ${
                isAuthed
                  ? `
                <td class="wan-dp-col-action">
                  <button class="wan-dp-action-icon btn-edit-row" data-id="${item.id}" title="Chỉnh sửa hàng">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M12 20h9"/>
                      <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>
                    </svg>
                  </button>
                  <button class="wan-dp-action-icon danger btn-delete-row" data-id="${item.id}" title="Xóa hàng trong baocao.xlsx">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <polyline points="3 6 5 6 21 6"/>
                      <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
                    </svg>
                  </button>
                </td>
              `
                  : ''
              }
            </tr>
          `;
        }
      });
    }

    this.modalOverlay.innerHTML = `
      <div class="wan-deploy-modal" role="dialog" aria-modal="true" aria-labelledby="deploy-modal-title">
        <!-- Header -->
        <div class="wan-deploy-header">
          <div class="wan-deploy-title-group">
            <div class="wan-deploy-badge">TRIỂN KHAI THỰC TẾ</div>
            <div>
              <h3 id="deploy-modal-title">Báo cáo tiến độ thực tế</h3>
            </div>
          </div>

          <div class="wan-deploy-header-actions">
            ${
              isAuthed
                ? `
              <div class="wan-deploy-role-pill authed" title="Đã nhập mã quản trị">
                <span class="wan-deploy-dot"></span>
                <span>Quản trị viên (Được phép thêm/sửa)</span>
              </div>
              <button id="btn-add-deploy-row" class="wan-btn-deploy primary" ${this.isAddingRow ? 'disabled' : ''}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                <span>Thêm</span>
              </button>
            `
                : `
              <div class="wan-deploy-role-pill readonly" title="Chưa xác thực mã đăng nhập">
                <span>Chế độ chỉ xem (Cần mã đăng nhập để sửa)</span>
              </div>
            `
            }
            <button id="btn-download-baocao" class="wan-btn-deploy secondary" title="Tải file baocao.xlsx">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                <polyline points="7 10 12 15 17 10"/>
                <line x1="12" y1="15" x2="12" y2="3"/>
              </svg>
              <span>Xuất baocao.xlsx</span>
            </button>
            <button id="btn-close-deploy-modal" class="wan-deploy-close-btn" title="Đóng bảng">&times;</button>
          </div>
        </div>

        <!-- Table Viewport -->
        <div class="wan-deploy-table-wrapper">
          <table class="wan-deploy-table">
            <thead>
              <tr>
                <th class="wan-dp-col-stt">STT</th>
                <th class="wan-dp-col-time">Thời gian</th>
                <th class="wan-dp-col-content">Nội dung</th>
                <th class="wan-dp-col-status">Tình trạng</th>
                ${isAuthed ? '<th class="wan-dp-col-action">Thao tác</th>' : ''}
              </tr>
            </thead>
            <tbody>
              ${tableRowsHtml}
            </tbody>
          </table>
        </div>
      </div>
    `;

    this.bindEvents();
  }

          bindEvents()       {
    if (!this.modalOverlay) return;

    // Close on backdrop click
    this.modalOverlay.addEventListener('click', (e) => {
      if (e.target === this.modalOverlay) {
        this.close();
      }
    });

    // Close button
    this.modalOverlay.querySelector('#btn-close-deploy-modal')?.addEventListener('click', () => {
      this.close();
    });

    // Close on Escape key
    const onKeyDown = (e               ) => {
      if (e.key === 'Escape') {
        this.close();
        window.removeEventListener('keydown', onKeyDown);
      }
    };
    window.addEventListener('keydown', onKeyDown);

    // Tự động điều chỉnh chiều cao (auto-resize height) cho các thẻ textarea khi nội dung dài
    this.modalOverlay.querySelectorAll                     ('.wan-dp-textarea').forEach((ta) => {
      const resize = () => {
        ta.style.height = 'auto';
        ta.style.height = `${Math.max(34, ta.scrollHeight)}px`;
      };
      ta.addEventListener('input', resize);
      requestAnimationFrame(resize);
    });

    // Button "+ Thêm"
    this.modalOverlay.querySelector('#btn-add-deploy-row')?.addEventListener('click', () => {
      if (!AuthManager.isAuthenticated()) return;
      this.isAddingRow = true;
      this.editingId = null;
      this.render();
      setTimeout(() => {
        const ta = this.modalOverlay?.querySelector('#input-new-content')                              ;
        ta?.focus();
      }, 50);
    });

    // Button Save New Row
    this.modalOverlay.querySelector('#btn-save-new-row')?.addEventListener('click', async () => {
      const timeInput = this.modalOverlay?.querySelector('#input-new-time')                           ;
      const contentInput = this.modalOverlay?.querySelector('#input-new-content')                                                 ;
      const statusSelect = this.modalOverlay?.querySelector('#select-new-status')                            ;

      if (!contentInput || !contentInput.value.trim()) {
        contentInput?.focus();
        return;
      }

      const timeVal = timeInput?.value.trim() || this.getFormattedCurrentTime();
      const contentVal = contentInput.value.trim();
      const statusVal = statusSelect?.value || 'Đang thực hiện';

      BaocaoStore.addItem({
        time: timeVal,
        content: contentVal,
        status: statusVal,
      });

      this.isAddingRow = false;
      this.render();
      await this.syncBaocaoToFile();
      this.showNotice('Đã thêm dòng mới vào baocao.xlsx');
    });

    // Button Cancel New Row
    this.modalOverlay.querySelector('#btn-cancel-new-row')?.addEventListener('click', () => {
      this.isAddingRow = false;
      this.render();
    });

    // Button Edit Row
    this.modalOverlay.querySelectorAll('.btn-edit-row').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = (btn               ).dataset.id;
        if (id) {
          this.editingId = id;
          this.isAddingRow = false;
          this.render();
        }
      });
    });

    // Button Save Edit Row
    this.modalOverlay.querySelectorAll('.btn-save-edit').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = (btn               ).dataset.id;
        if (!id) return;

        const timeInput = this.modalOverlay?.querySelector(`#edit-time-${id}`)                           ;
        const contentInput = this.modalOverlay?.querySelector(`#edit-content-${id}`)                                                 ;
        const statusSelect = this.modalOverlay?.querySelector(`#edit-status-${id}`)                            ;

        if (!contentInput || !contentInput.value.trim()) {
          contentInput?.focus();
          return;
        }

        BaocaoStore.updateItem(id, {
          time: timeInput?.value.trim() || this.getFormattedCurrentTime(),
          content: contentInput.value.trim(),
          status: statusSelect?.value || 'Đang thực hiện',
        });

        this.editingId = null;
        this.render();
        await this.syncBaocaoToFile();
        this.showNotice('Đã cập nhật hàng trong baocao.xlsx');
      });
    });

    // Button Cancel Edit Row
    this.modalOverlay.querySelectorAll('.btn-cancel-edit').forEach((btn) => {
      btn.addEventListener('click', () => {
        this.editingId = null;
        this.render();
      });
    });

    // Button Delete Row
    this.modalOverlay.querySelectorAll('.btn-delete-row').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = (btn               ).dataset.id;
        if (!id) return;

        const items = BaocaoStore.getItems();
        const itemToDelete = items.find((i) => i.id === id);

        const confirmMsg = itemToDelete
          ? `Bạn có chắc chắn muốn xóa dòng báo cáo này khỏi baocao.xlsx?\n\n• Thời gian: ${itemToDelete.time}\n• Nội dung: ${itemToDelete.content}\n• Trạng thái: ${itemToDelete.status}`
          : 'Bạn có chắc chắn muốn xóa dòng báo cáo này khỏi baocao.xlsx?';

        if (confirm(confirmMsg)) {
          // 1. Xóa khỏi kho dữ liệu BaocaoStore
          BaocaoStore.deleteItem(id);

          // 2. Đồng bộ cập nhật xóa hàng tương ứng trong file baocao.xlsx
          await this.syncBaocaoToFile();

          // 3. Render lại bảng hiển thị
          this.render();
          this.showNotice('Đã xóa hàng tương ứng trong baocao.xlsx');
        }
      });
    });

    // Button Download Excel baocao.xlsx
    this.modalOverlay.querySelector('#btn-download-baocao')?.addEventListener('click', () => {
      this.downloadExcelFile();
    });
  }

  // Đồng bộ cập nhật toàn bộ danh sách sang file baocao.xlsx với xác thực an toàn
          async syncBaocaoToFile()                {
    const items = BaocaoStore.getItems();
    const token = AuthManager.getAuthToken();
    try {
      await fetch('/api/baocao', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify(items),
      });
    } catch {
      // Offline / standalone browser mode: localStorage is already updated
    }
  }

  // Hiển thị thông báo toast nhanh cho người dùng
          showNotice(message        )       {
    const existing = document.querySelector('.wan-deploy-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = 'wan-deploy-toast';
    toast.textContent = message;
    document.body.appendChild(toast);

    requestAnimationFrame(() => {
      toast.classList.add('show');
    });

    setTimeout(() => {
      toast.classList.remove('show');
      setTimeout(() => toast.remove(), 250);
    }, 2500);
  }

  // Generate and download actual baocao.xlsx
          downloadExcelFile()       {
    const items = BaocaoStore.getItems();

    // Construct XML Spreadsheet 2003 which Excel opens natively without any third-party zip library
    let xml = `<?xml version="1.0" encoding="UTF-8"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40">
 <Styles>
  <Style ss:ID="Header">
   <Font ss:Bold="1" ss:Color="#FFFFFF" ss:FontName="Calibri" ss:Size="11"/>
   <Interior ss:Color="#29348F" ss:Pattern="Solid"/>
   <Alignment ss:Horizontal="Center" ss:Vertical="Center"/>
   <Borders>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#000000"/>
   </Borders>
  </Style>
  <Style ss:ID="Data">
   <Font ss:FontName="Calibri" ss:Size="11"/>
   <Borders>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#E2E8F0"/>
   </Borders>
  </Style>
  <Style ss:ID="Time">
   <Font ss:FontName="Calibri" ss:Size="11" ss:Bold="1"/>
   <Alignment ss:Horizontal="Center" ss:Vertical="Center"/>
   <Borders>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#E2E8F0"/>
   </Borders>
  </Style>
 </Styles>
 <Worksheet ss:Name="TrienKhaiThucTe">
  <Table>
   <Column ss:Width="130"/>
   <Column ss:Width="380"/>
   <Column ss:Width="120"/>
   <Row ss:Height="26">
    <Cell ss:StyleID="Header"><Data ss:Type="String">time</Data></Cell>
    <Cell ss:StyleID="Header"><Data ss:Type="String">content</Data></Cell>
    <Cell ss:StyleID="Header"><Data ss:Type="String">status</Data></Cell>
   </Row>`;

    items.forEach((item) => {
      const sanitizeExcelCell = (val        ) => {
        let text = val || '';
        // Phòng chống CSV / Excel Formula Injection (nếu chuỗi bắt đầu bằng =, +, -, @)
        if (/^[=+\-@]/.test(text)) {
          text = "'" + text;
        }
        return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      };

      xml += `
   <Row ss:Height="22">
    <Cell ss:StyleID="Time"><Data ss:Type="String">${sanitizeExcelCell(item.time)}</Data></Cell>
    <Cell ss:StyleID="Data"><Data ss:Type="String">${sanitizeExcelCell(item.content)}</Data></Cell>
    <Cell ss:StyleID="Data"><Data ss:Type="String">${sanitizeExcelCell(item.status)}</Data></Cell>
   </Row>`;
    });

    xml += `
  </Table>
 </Worksheet>
</Workbook>`;

    const blob = new Blob([xml], { type: 'application/vnd.ms-excel;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'baocao.xlsx';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      a.remove();
      URL.revokeObjectURL(url);
    }, 100);
  }
}



